/* ── adminTheme.js — Shared theme tokens for all admin pages ─────────────────
 * Import useAdminTheme() in any admin sub-page to get T (tokens) and helpers.
 * AdminDashboard.jsx injects the CSS variables and DM Sans font.
 * ─────────────────────────────────────────────────────────────────────────── */
import { createContext, useContext } from 'react';

export const AdminThemeContext = createContext({ themeKey: 'light', T: null, toggleTheme: () => {} });

export function useAdminTheme() {
  return useContext(AdminThemeContext);
}

